abstract class Shape{abstract double area();}class Circle extends Shape{double r;Circle(double r){this.r=r;}double area(){return Math.PI*r*r;}}class Rectangle extends Shape{double w,h;Rectangle(double w,double h){this.w=w;this.h=h;}double area(){return w*h;}}class Triangle extends Shape{double b,h;Triangle(double b,double h){this.b=b;this.h=h;}double area(){return .5*b*h;}}public class ShapeDemo{public static void main(String[]x){Shape[] a={new Circle(2),new Rectangle(3,4),new Triangle(4,5)};double sum=0,max=0;for(Shape s:a){double v=s.area();System.out.println(s.getClass().getSimpleName()+": "+v);sum+=v;max=Math.max(max,v);}System.out.println("Total="+sum+", Largest="+max);}}
